// Return the cgroup_subsys_state for the (@task, @subsys_id) pair.  The
// synchronization rules are the same as task_css_set_check().
fn cgroup_is_descendant(cgrp: *mut cgroup, ancestor: *mut cgroup) -> bool {
if (unsafe { (*cgrp).root }) != unsafe { (*ancestor).root } || (unsafe { (*cgrp).level }) < unsafe { (*ancestor).level } {
return false;
}
(unsafe { *(core::ptr::addr_of_mut!((*cgrp).__slate_anon_38.__slate_anon_0.ancestors) as *mut *mut cgroup).wrapping_offset((*ancestor).level as isize) }) == ancestor
}

